css:
.tailoredsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2433;
    background: linear-gradient(160deg, #f4f1ea 0%, #eae4d6 100%);
    border-radius: 18px;
}

.tailoredsim-container * {
    box-sizing: border-box;
}

.tailoredsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11233f 0%, #1d3a63 55%, #2b4a7a 100%);
    color: #f6f2e7;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 35, 63, 0.32);
}

.tailoredsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f6f2e7;
}

.tailoredsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c873;
    background: rgba(231, 200, 115, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.tailoredsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4ddca;
}

.tailoredsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b3a55;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.tailoredsim-period-counter #currentDay,
.tailoredsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11233f;
}

.tailoredsim-round-name {
    background: #dfd4b8;
    color: #11233f;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.tailoredsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a1c;
    background: #f3e6c8;
    padding: 4px 12px;
    border-radius: 999px;
}

.tailoredsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.tailoredsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2d9c4;
    box-shadow: 0 4px 14px rgba(17, 35, 63, 0.06);
    border-top: 4px solid #2b4a7a;
}

.tailoredsim-card-nps { border-top-color: #1f7a5c; }
.tailoredsim-card-margin { border-top-color: #b8862b; }
.tailoredsim-card-faculty { border-top-color: #6a4fb0; }
.tailoredsim-card-delivery { border-top-color: #2b6fb0; }

.tailoredsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a7058;
}

.tailoredsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11233f;
}

.tailoredsim-card-nps .tailoredsim-value { color: #1f7a5c; }
.tailoredsim-card-margin .tailoredsim-value { color: #b8862b; }
.tailoredsim-card-faculty .tailoredsim-value { color: #6a4fb0; }
.tailoredsim-card-delivery .tailoredsim-value { color: #2b6fb0; }

.tailoredsim-sublabel {
    font-size: 0.75rem;
    color: #8a7f64;
    line-height: 1.35;
}

/* state highlights */
.tailoredsim-margin-fail .tailoredsim-value { color: #c0392b; }
.tailoredsim-margin-ok .tailoredsim-value { color: #1f7a5c; }
.tailoredsim-faculty-over { border-top-color: #c0392b; }
.tailoredsim-faculty-over .tailoredsim-value { color: #c0392b; }
.tailoredsim-nps-target .tailoredsim-value { color: #1f7a5c; }

.tailoredsim-resource-bar {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-bottom: 18px;
}

.tailoredsim-resource {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11233f;
    color: #f0ead9;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.tailoredsim-resource span:last-child {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c873;
}

.tailoredsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #b8862b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 35, 63, 0.05);
}

.tailoredsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.tailoredsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11233f;
    margin-bottom: 6px;
}

.tailoredsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4255;
}

.tailoredsim-briefing-text strong { color: #1f7a5c; }
.tailoredsim-briefing-text em { color: #8a5a1c; font-style: italic; }

.tailoredsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2d9c4;
    box-shadow: 0 4px 14px rgba(17, 35, 63, 0.06);
}

.tailoredsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11233f;
    border-bottom: 2px solid #ece4d2;
    padding-bottom: 8px;
}

.tailoredsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #23324d;
    margin: 14px 0 6px;
}

.tailoredsim-container select,
.tailoredsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d6cbb1;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f1;
    color: #1d2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.tailoredsim-container select:focus,
.tailoredsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b8862b;
    box-shadow: 0 0 0 3px rgba(184, 134, 43, 0.18);
}

.tailoredsim-container select option {
    background-color: #fffdf8;
    color: #1d2433;
}

.tailoredsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b8862b;
}

.tailoredsim-range-readout,
.tailoredsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #23324d;
    margin-top: 4px;
}

.tailoredsim-range-readout span:last-child,
.tailoredsim-alloc-readout span:nth-child(2) {
    color: #1f7a5c;
    font-weight: 800;
}

.tailoredsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.tailoredsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f1e4;
    border: 1px solid #e4dbc6;
    border-radius: 9px;
    padding: 8px 12px;
}

.tailoredsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #23324d;
}

.tailoredsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.tailoredsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.tailoredsim-container .btn-primary {
    background: linear-gradient(135deg, #11233f 0%, #2b4a7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f6f2e7;
    box-shadow: 0 6px 16px rgba(17, 35, 63, 0.28);
}

.tailoredsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.tailoredsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d6cbb1;
    color: #7a7058;
}

.tailoredsim-coach {
    background: #11233f;
    color: #f0ead9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 35, 63, 0.24);
}

.tailoredsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c873;
    margin-bottom: 8px;
}

.tailoredsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.tailoredsim-coach-body strong { color: #f3d894; }
.tailoredsim-coach-body em { color: #f0b27a; font-style: italic; }

.tailoredsim-history,
.tailoredsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2d9c4;
    box-shadow: 0 4px 14px rgba(17, 35, 63, 0.06);
}

.tailoredsim-history h3,
.tailoredsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11233f;
}

.tailoredsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #23324d;
}

.tailoredsim-container table#usfHistoryTable th {
    background: #efe8d6;
    color: #11233f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd2b8;
}

.tailoredsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ead9;
}

.tailoredsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ec;
}

.tailoredsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .tailoredsim-container {
        padding: 14px;
    }
    .tailoredsim-header h1 {
        font-size: 1.7rem;
    }
    .tailoredsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .tailoredsim-value {
        font-size: 2rem;
    }
    .tailoredsim-clock {
        margin-left: 0;
    }
    .tailoredsim-period-counter {
        font-size: 0.88rem;
    }
    .tailoredsim-resource-bar {
        grid-template-columns: 1fr;
    }
    .tailoredsim-resource {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .tailoredsim-alloc-row {
        flex-wrap: wrap;
    }
    .tailoredsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .tailoredsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, tailoredsim) ---- */
.tailoredsim-completion { padding: 8px 4px 4px; }
.tailoredsim-cm-head { text-align: center; margin-bottom: 16px; }
.tailoredsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.tailoredsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b9b7d; }
.tailoredsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.tailoredsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.tailoredsim-cm-yes { background: rgba(31,122,82,0.14); color: #1a7059; border: 1px solid rgba(31,122,82,0.5); }
.tailoredsim-cm-no { background: rgba(192,86,31,0.12); color: #b0521f; border: 1px solid rgba(192,86,31,0.45); }
.tailoredsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.tailoredsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(42,74,122,0.08); border: 1px solid rgba(42,74,122,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.tailoredsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2a4a7a; }
.tailoredsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.tailoredsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.tailoredsim-cm-insights { margin: 0; padding-left: 20px; }
.tailoredsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

