(function() {
    'use strict';

    class TailoredAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Tailored Fit`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD).
            this.START_NPS = 35;            // below the ≥65 target; flagship hit 74
            this.TARGET_NPS = 65;           // above exec-ed benchmark
            this.FLAGSHIP_NPS = 74;         // delighted-but-loss flagship
            this.START_MARGIN = 9;          // last year's over-customised flagship margin
            this.MARGIN_FLOOR = 25;         // dean's non-negotiable floor
            this.MARGIN_TARGET = 32;        // unit standard
            this.START_FACULTY = 80;        // marquee already >80% utilised
            this.FACULTY_CAP = 85;          // burnout / attrition risk above this
            this.START_DELIVERY = 50;       // on-time delivery index (0-100)
            this.BUDGET_CAP = 4.5;          // USD 4.5M fixed, in millions
            this.FACDAYS_CAP = 70;          // estimated faculty-days for the rollout
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    nps: this.START_NPS,
                    margin: this.START_MARGIN,
                    faculty: this.START_FACULTY,
                    delivery: this.START_DELIVERY,
                    budgetUsed: 0,
                    facdaysUsed: 0,
                    marginBreached: false,
                    facultyBurned: false,
                    npsHistory: [this.START_NPS],
                    marginHistory: [this.START_MARGIN],
                    facultyHistory: [this.START_FACULTY],
                    deliveryHistory: [this.START_DELIVERY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    scope: `qualify`,
                    regional: `real`,
                    fund: 60,
                    offshelf: 40,
                    configured: 45,
                    bespoke: 15,
                    core: `coreplus`,
                    bespokefocus: `differentiator`,
                    sequence: `pilot`,
                    marquee: 20,
                    regionalfac: 35,
                    ttf: 15,
                    reuse: 60,
                    scorecard: `balanced`,
                    renewal: `proof`,
                    offer: `decline`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sc = document.getElementById(`scopeInput`);
                const rg = document.getElementById(`regionalInput`);
                const fu = document.getElementById(`fundInput`);
                if (sc) decisions.scope = sc.value;
                if (rg) decisions.regional = rg.value;
                if (fu) decisions.fund = parseInt(fu.value, 10);
                if (!Number.isFinite(decisions.fund) || decisions.fund < 0 || decisions.fund > 100) {
                    warn(`warn_fund_range`); return false;
                }
            } else if (round === 2) {
                const off = document.getElementById(`offshelfInput`);
                const cfg = document.getElementById(`configuredInput`);
                const bsp = document.getElementById(`bespokeInput`);
                const core = document.getElementById(`coreInput`);
                const bf = document.getElementById(`bespokefocusInput`);
                if (off) decisions.offshelf = parseInt(off.value, 10);
                if (cfg) decisions.configured = parseInt(cfg.value, 10);
                if (bsp) decisions.bespoke = parseInt(bsp.value, 10);
                if (core) decisions.core = core.value;
                if (bf) decisions.bespokefocus = bf.value;
                const parts = [decisions.offshelf, decisions.configured, decisions.bespoke];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_mix_negative`); return false;
                }
                const total = decisions.offshelf + decisions.configured + decisions.bespoke;
                if (total !== 100) {
                    warn(`warn_mix_total`); return false;
                }
            } else if (round === 3) {
                const seq = document.getElementById(`sequenceInput`);
                const mq = document.getElementById(`marqueeInput`);
                const rf = document.getElementById(`regionalfacInput`);
                const tf = document.getElementById(`ttfInput`);
                const ru = document.getElementById(`reuseInput`);
                if (seq) decisions.sequence = seq.value;
                if (mq) decisions.marquee = parseInt(mq.value, 10);
                if (rf) decisions.regionalfac = parseInt(rf.value, 10);
                if (tf) decisions.ttf = parseInt(tf.value, 10);
                if (ru) decisions.reuse = parseInt(ru.value, 10);
                const days = [decisions.marquee, decisions.regionalfac, decisions.ttf];
                if (days.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_days_negative`); return false;
                }
                if (decisions.marquee + decisions.regionalfac + decisions.ttf !== this.FACDAYS_CAP) {
                    warn(`warn_days_total`); return false;
                }
                if (!Number.isFinite(decisions.reuse) || decisions.reuse < 0 || decisions.reuse > 100) {
                    warn(`warn_reuse_range`); return false;
                }
            } else if (round === 4) {
                const scd = document.getElementById(`scorecardInput`);
                const ren = document.getElementById(`renewalInput`);
                const off = document.getElementById(`offerInput`);
                const cv = document.getElementById(`convictionInput`);
                if (scd) decisions.scorecard = scd.value;
                if (ren) decisions.renewal = ren.value;
                if (off) decisions.offer = off.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Four KPI deltas. Positive faculty delta = MORE utilisation (worse if it pushes past the cap).
            let npsDelta = 0, marginDelta = 0, facultyDelta = 0, deliveryDelta = 0;
            let spend = 0, facdays = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Qualify the brief vs accept-whole (full bespoke) vs over-standardise.
                if (d.scope === `qualify`) {
                    npsDelta += 5; marginDelta += 5; deliveryDelta += 3; coachKey = `coach_r1_qualify`;
                } else if (d.scope === `fullbespoke`) {
                    // Replays the flagship: client pleased now, margin & bench wrecked.
                    npsDelta += 4; marginDelta -= 8; facultyDelta += 3; coachKey = `coach_r1_fullbespoke`;
                } else { // standardise
                    npsDelta -= 9; marginDelta += 5; coachKey = `coach_r1_standardise`;
                }

                // Reading real regional difference vs everything vs nothing.
                if (d.regional === `real`) {
                    npsDelta += 5; marginDelta += 3; coachKey = (d.scope === `qualify`) ? `coach_r1_sharp` : coachKey;
                } else if (d.regional === `all`) {
                    npsDelta += 2; marginDelta -= 6; facultyDelta += 2; coachKey = `coach_r1_regionall`;
                } else { // none
                    npsDelta -= 7; marginDelta += 2; coachKey = `coach_r1_regionnone`;
                }

                // Margin discipline applied to scoping & renegotiation.
                if (d.fund >= 60) { marginDelta += 4; }
                else if (d.fund <= 25) { marginDelta -= 6; coachKey = `coach_r1_lowfund`; }

                summaryKey = (d.scope === `qualify` && d.regional === `real`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Off-the-shelf / configured / bespoke mix. The configured MIDDLE is the high-leverage zone.
                const off = d.offshelf, cfg = d.configured, bsp = d.bespoke;

                // NPS rewards perceived customisation: configured ~0.9x bespoke value at a fraction of cost.
                npsDelta += Math.round((cfg * 0.10 + bsp * 0.11 + off * 0.01) - 5);
                // Margin: off-the-shelf and configured protect margin; heavy bespoke destroys it.
                marginDelta += Math.round((off * 0.05 + cfg * 0.07 - bsp * 0.28) + 1);
                // Faculty: bespoke is faculty-intensive; configured is light; off-the-shelf is near-free.
                facultyDelta += Math.round((bsp * 0.16 + cfg * 0.02) - 3);
                // Design cost: configured ~$35k/module-share, bespoke ~$90k, off-the-shelf cheap.
                spend += (off * 0.004 + cfg * 0.012 + bsp * 0.030);

                // Missing the configured middle (Common Error 4): treating it as off-vs-bespoke only.
                if (cfg <= 10 && bsp >= 40) {
                    marginDelta -= 6; facultyDelta += 3; coachKey = `coach_r2_nomiddle`;
                } else if (cfg <= 10 && off >= 70) {
                    npsDelta -= 6; coachKey = `coach_r2_allshelf`;
                } else if (cfg >= 40 && bsp <= 25 && off <= 50) {
                    npsDelta += 4; marginDelta += 3; coachKey = `coach_r2_middle`;
                }

                // Platform-and-modules structure.
                switch (d.core) {
                    case `coreplus`: npsDelta += 5; marginDelta += 4; deliveryDelta += 3; coachKey = `coach_r2_coreplus`; break;
                    case `thincore`: npsDelta += 2; marginDelta -= 6; facultyDelta += 3; coachKey = `coach_r2_thincore`; break;
                    case `onlycore`: npsDelta -= 7; marginDelta += 2; coachKey = `coach_r2_onlycore`; break;
                }

                // Where bespoke is concentrated.
                switch (d.bespokefocus) {
                    case `differentiator`: npsDelta += 4; coachKey = (d.core === `coreplus`) ? `coach_r2_concentrated` : coachKey; break;
                    case `everywhere`: npsDelta -= 3; marginDelta -= 4; facultyDelta += 2; coachKey = `coach_r2_spread`; break;
                    case `generic`: npsDelta -= 4; marginDelta -= 3; coachKey = `coach_r2_genericbespoke`; break;
                }

                summaryKey = (d.core === `coreplus` && cfg >= 40 && bsp <= 25 && d.bespokefocus === `differentiator`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Stage the rollout under capacity + margin.
                const mq = d.marquee, rf = d.regionalfac, tf = d.ttf;
                facdays = mq + rf + tf; // already validated to total 70

                // Sequencing: pilot-then-scale de-risks; parallel risks replicating a flaw 600x.
                switch (d.sequence) {
                    case `pilot`: deliveryDelta += 11; npsDelta += 4; coachKey = `coach_r3_pilot`; break;
                    case `parallel`: deliveryDelta -= 10; npsDelta -= 4; coachKey = `coach_r3_parallel`; break;
                    case `staggered`: deliveryDelta += 6; npsDelta += 2; coachKey = `coach_r3_staggered`; break;
                }

                // Marquee faculty-days drive utilisation and cost. Over-booking burns the bench.
                facultyDelta += Math.round((mq - 18) * 0.40);
                spend += mq * 0.024 + rf * 0.0095 + tf * 0.003; // $24k / $9.5k per day; TtF cheap per day
                if (tf >= 10) spend += 0.045; // a train-the-facilitator cohort (~$45k) extends the bench

                if (mq >= 32) {
                    facultyDelta += 5; npsDelta += 3; coachKey = `coach_r3_overbook`;
                } else if (mq <= 22 && rf >= 28 && tf >= 8) {
                    npsDelta += 4; marginDelta += 3; coachKey = `coach_r3_balanced`;
                } else if (rf + tf < 30) {
                    facultyDelta += 3; coachKey = `coach_r3_thinbench`;
                }

                // Marquee names still carry the differentiating modules — too few hollows out perceived quality.
                // Graduated: stripping the bench to please faculty-headroom must not out-score a balanced allocation.
                if (mq < 8) { npsDelta -= 12; coachKey = `coach_r3_nomarquee`; }
                else if (mq < 12) { npsDelta -= 8; coachKey = `coach_r3_nomarquee`; }
                else if (mq < 16) { npsDelta -= 3; }

                // Pricing configured-module reuse into the margin bridge.
                if (d.reuse >= 60) { marginDelta += 6; }
                else if (d.reuse >= 35) { marginDelta += 3; }
                else { marginDelta -= 4; coachKey = `coach_r3_noreuse`; }

                summaryKey = (d.sequence !== `parallel` && mq <= 22 && d.reuse >= 60) ? `sum_r3_good` : (d.sequence === `parallel` || mq >= 32 ? `sum_r3_risk` : `sum_r3_weak`);
            } else if (round === 4) {
                // Lock the scorecard + pitch the academy. Single-KPI optimisation is the trap.
                switch (d.scorecard) {
                    case `balanced`: npsDelta += 5; marginDelta += 5; deliveryDelta += 5; coachKey = `coach_r4_balanced`; break;
                    case `maxnps`: npsDelta += 8; marginDelta -= 12; facultyDelta += 6; coachKey = `coach_r4_maxnps`; break;
                    case `maxmargin`: npsDelta -= 12; marginDelta += 7; coachKey = `coach_r4_maxmargin`; break;
                }

                // Renewal framing.
                switch (d.renewal) {
                    case `proof`: npsDelta += 4; marginDelta += 3; deliveryDelta += 2; coachKey = (d.scorecard === `balanced`) ? `coach_r4_proof` : coachKey; break;
                    case `crowdpleaser`: npsDelta += 3; marginDelta -= 7; facultyDelta += 4; coachKey = `coach_r4_crowdpleaser`; break;
                    case `discount`: marginDelta -= 8; coachKey = `coach_r4_discount`; break;
                }

                // The $1M-for-full-bespoke offer: declining protects the model.
                switch (d.offer) {
                    case `decline`: marginDelta += 4; facultyDelta -= 4; coachKey = (d.scorecard === `balanced`) ? `coach_r4_decline` : coachKey; break;
                    case `accept`: npsDelta += 4; marginDelta -= 8; facultyDelta += 9; coachKey = `coach_r4_accept`; break;
                    case `partial`: npsDelta += 3; marginDelta += 1; facultyDelta += 2; coachKey = `coach_r4_partial`; break;
                }

                // Conviction nudges NPS (a convincing pitch lands).
                npsDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.scorecard === `balanced` && d.renewal === `proof` && d.offer === `decline`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            ds.facdaysUsed = ds.facdaysUsed + facdays;

            // If the engagement runs over the fixed budget, the overspend comes straight out of margin.
            if (ds.budgetUsed > this.BUDGET_CAP) {
                const over = ds.budgetUsed - this.BUDGET_CAP;
                marginDelta -= Math.round(over * 12); // each $1M over ~ -12 margin points
                ds.budgetUsed = this.BUDGET_CAP;
            }

            // Apply deltas with 0-100 / sensible bounds.
            ds.nps = Math.max(0, Math.min(100, ds.nps + npsDelta));
            ds.margin = Math.max(0, Math.min(60, ds.margin + marginDelta));
            ds.faculty = Math.max(0, Math.min(100, ds.faculty + facultyDelta));
            ds.delivery = Math.max(0, Math.min(100, ds.delivery + deliveryDelta));

            // Flags.
            if (round === this.ROUNDS.length && ds.margin < this.MARGIN_FLOOR) ds.marginBreached = true;
            if (ds.faculty > this.FACULTY_CAP) ds.facultyBurned = true;

            ds.npsHistory.push(Math.round(ds.nps));
            ds.marginHistory.push(Math.round(ds.margin));
            ds.facultyHistory.push(Math.round(ds.faculty));
            ds.deliveryHistory.push(Math.round(ds.delivery));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100, clamped) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                nps: Math.round(ds.nps),
                npsDelta: Math.round(npsDelta),
                margin: Math.round(ds.margin),
                marginDelta: Math.round(marginDelta),
                faculty: Math.round(ds.faculty),
                facultyDelta: Math.round(facultyDelta),
                delivery: Math.round(ds.delivery),
                deliveryDelta: Math.round(deliveryDelta),
                budgetUsed: ds.budgetUsed,
                facdaysUsed: ds.facdaysUsed,
                marginBreached: ds.marginBreached,
                facultyBurned: ds.facultyBurned,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

