        _wireSlider(inputId, readoutId) {
            const el = document.getElementById(inputId);
            const ro = document.getElementById(readoutId);
            if (el && ro) {
                ro.textContent = el.value;
                el.addEventListener(`input`, function() { ro.textContent = el.value; });
            }
        }

        _wireAlloc(ids, readoutId, cap) {
            const ro = document.getElementById(readoutId);
            const recompute = function() {
                let total = 0;
                ids.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (ro) {
                    ro.textContent = total;
                    const bar = ro.parentElement;
                    if (bar) bar.style.color = (total !== cap) ? `#c0392b` : ``;
                }
            };
            ids.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

