        // Composite written to domainState.performance.overallScore each period, CLAMPED to [0,100]
        // for the reporting layer. Inner formula copied VERBATIM from v1.0.0 getPerformanceSummary
        // (which is intentionally left unclamped -> scoring unchanged).
        _composite(ds) {
            const nps = Math.round(ds.nps);
            const margin = Math.round(ds.margin);
            const faculty = Math.round(ds.faculty);
            const delivery = Math.round(ds.delivery);
            let facultyScore;
            if (faculty > 78) facultyScore = Math.max(0, 100 - (faculty - 78) * 5);
            else if (faculty >= 60) facultyScore = 100;
            else facultyScore = Math.max(0, 100 - (60 - faculty) * 2.2);
            const composite = Math.round(nps * 0.30 + Math.min(40, margin) * 1.25 + facultyScore * 0.20 + delivery * 0.20);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? Math.max(0, Math.min(100, s.composite)) : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.allFour;
            const badge = met
                ? `<span class="tailoredsim-cm-badge tailoredsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="tailoredsim-cm-badge tailoredsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const failBadge = (s.facultyOk === false)
                ? ` <span class="tailoredsim-cm-badge tailoredsim-cm-no">` + T(`cm_burned`) + `</span>`
                : ((s.marginOk === false) ? ` <span class="tailoredsim-cm-badge tailoredsim-cm-no">` + T(`cm_margin`) + `</span>` : ``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="tailoredsim-cm-metric"><span class="tailoredsim-cm-mv">` + Math.round(s.nps || 0) + `</span><span class="tailoredsim-cm-ml">` + T(`cm_m_nps`) + `</span></div>`
                + `<div class="tailoredsim-cm-metric"><span class="tailoredsim-cm-mv">` + Math.round(s.margin || 0) + `%</span><span class="tailoredsim-cm-ml">` + T(`cm_m_margin`) + `</span></div>`
                + `<div class="tailoredsim-cm-metric"><span class="tailoredsim-cm-mv">` + Math.round(s.faculty || 0) + `%</span><span class="tailoredsim-cm-ml">` + T(`cm_m_faculty`) + `</span></div>`
                + `<div class="tailoredsim-cm-metric"><span class="tailoredsim-cm-mv">` + Math.round(s.delivery || 0) + `</span><span class="tailoredsim-cm-ml">` + T(`cm_m_delivery`) + `</span></div>`;
            return ``
                + `<div class="tailoredsim-completion">`
                +   `<div class="tailoredsim-cm-head">`
                +     `<div class="tailoredsim-cm-score">` + score + `<span class="tailoredsim-cm-score-max">/100</span></div>`
                +     `<div class="tailoredsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="tailoredsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="tailoredsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="tailoredsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const nps = Math.round(ds.nps);
            const margin = Math.round(ds.margin);
            const faculty = Math.round(ds.faculty);
            const delivery = Math.round(ds.delivery);

            const npsOk = nps >= this.TARGET_NPS;
            const marginOk = margin >= this.MARGIN_FLOOR;
            const facultyOk = faculty <= this.FACULTY_CAP;
            const deliveryOk = delivery >= 65;
            const allFour = npsOk && marginOk && facultyOk && deliveryOk;

            // Composite: all four KPIs matter; faculty is scored as a healthy operating BAND,
            // not pure headroom — over-booking past ~78% burns the bench, but starving the bench
            // far below ~60% (idle, no durable capability) is also sub-optimal. This keeps a balanced
            // marquee allocation as the genuine peak instead of rewarding stripping marquee to zero.
            let facultyScore;
            if (faculty > 78) facultyScore = Math.max(0, 100 - (faculty - 78) * 5);
            else if (faculty >= 60) facultyScore = 100;
            else facultyScore = Math.max(0, 100 - (60 - faculty) * 2.2);
            const composite = Math.round(nps * 0.30 + Math.min(40, margin) * 1.25 + facultyScore * 0.20 + delivery * 0.20);

            let performanceKey = `grade_misscoped`;
            if (allFour && composite >= 78) performanceKey = `grade_renewable`;
            else if (allFour) performanceKey = `grade_balanced`;
            else if (npsOk && !marginOk) performanceKey = `grade_crowdpleaser`;
            else if (marginOk && !npsOk) performanceKey = `grade_generic`;
            else if (!facultyOk) performanceKey = `grade_burned`;
            else if (npsOk || marginOk) performanceKey = `grade_partly`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (allFour) insights.push(window.mySimulation.t(`insight_renewable`));
            if (npsOk && !marginOk) insights.push(window.mySimulation.t(`insight_crowdpleaser`));
            if (marginOk && !npsOk) insights.push(window.mySimulation.t(`insight_generic`));
            if (!facultyOk) insights.push(window.mySimulation.t(`insight_burned`));
            if (!deliveryOk) insights.push(window.mySimulation.t(`insight_late`));
            if (margin >= this.MARGIN_TARGET && npsOk) insights.push(window.mySimulation.t(`insight_target`));
            if (!npsOk && !marginOk) insights.push(window.mySimulation.t(`insight_misscoped`));

            return {
                nps: nps,
                margin: margin,
                faculty: faculty,
                delivery: delivery,
                npsOk: npsOk,
                marginOk: marginOk,
                facultyOk: facultyOk,
                deliveryOk: deliveryOk,
                allFour: allFour,
                composite: composite,
                totalScore: Math.max(0, Math.min(100, composite)),
                overallScore: Math.max(0, Math.min(100, composite)),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.faculty > this.FACULTY_CAP) return window.mySimulation.t(`hint_burned`);
            if (state.currentPeriod >= 2 && ds.margin < this.MARGIN_FLOOR) return window.mySimulation.t(`hint_margin`);
            if (state.currentPeriod >= 2 && ds.nps < 45) return window.mySimulation.t(`hint_nps`);
            if (state.currentPeriod >= 3 && ds.delivery < 55) return window.mySimulation.t(`hint_delivery`);
            if (ds.nps >= this.TARGET_NPS && ds.margin >= this.MARGIN_FLOOR && ds.faculty <= this.FACULTY_CAP) return window.mySimulation.t(`hint_strong`);
            return null;
        }

